(()=>{const score=document.querySelector('#hud-score');let previous=score.textContent;new MutationObserver(()=>{const value=score.textContent;if(value===previous)return;previous=value;if(document.body.classList.contains('motion-off')||matchMedia('(prefers-reduced-motion: reduce)').matches)return;score.getAnimations().forEach(a=>a.cancel());score.animate([{scale:'1'},{scale:'1.4',offset:.4},{scale:'.95',offset:.75},{scale:'1'}],{duration:550,easing:'ease-out'});}).observe(score,{childList:true,characterData:true,subtree:true});})();